// Root-allocated CPU slot only. Composite every real local probe/render JPEG.
// Creates pending eye evidence, never a human-approval JSON automatically.
import fs from'node:fs';import path from'node:path';import assert from'node:assert/strict';import{createHash}from'node:crypto';import sharp from'sharp';
const root=process.env.D1_LOCAL_ROOT??'/private/tmp/ys/ys-chain-d1v1-final-local-bundle-v2-20261024',mode=process.env.D1_LOCAL_MODE??'probe',base='/private/tmp/ys/ys-chain-d1v1-production-r15',read=p=>JSON.parse(fs.readFileSync(p)),sha=p=>createHash('sha256').update(fs.readFileSync(p)).digest('hex');assert(['probe','render'].includes(mode));
const reportFile=root+'/'+mode+'/report.json',p=read(reportFile);assert(p.allRequestedActuallyRendered&&p.allReplacementPhysicalPass&&Object.values(p.protection).every(Boolean));assert(p.actualImages.length===p.renders);
const cache=root+'/'+mode+'-composite-cache',out=root+'/'+mode+'-composite-review';assert(!fs.existsSync(cache)&&!fs.existsSync(out));fs.mkdirSync(cache+'/blender',{recursive:true});fs.mkdirSync(out+'/frames',{recursive:true});fs.mkdirSync(out+'/sheets');
for(const f of['plan.json','ys-chain-d1v1.json','phrase-times.json'])fs.symlinkSync(base+'/'+f,cache+'/'+f);fs.symlinkSync(base+'/blender/data.json',cache+'/blender/data.json');fs.symlinkSync(p.raw,cache+'/blender/desk');
process.env.EM_FILM_CACHE=cache;process.env.DESK_ALLOW_MISSING='1';const{vertFrame}=await import('./desk-axes-frame.mjs'),plan=read(cache+'/plan.json')[0],timed=read(cache+'/ys-chain-d1v1.json'),data=read(base+'/blender/data.json');const clip={...plan,duration:timed.duration,scenes:plan.scenes.map((s,i)=>({...s,start:timed.scenes[i].start,end:timed.scenes[i].end,captions:timed.scenes[i].captions}))};
const rows=[],pages=[];let tiles=[];
for(let i=0;i<p.actualImages.length;i++){
 const image=p.actualImages[i],j=image.frame,t=j/30;assert.equal(sha(image.path),image.sha256);const sc=clip.scenes.find(s=>s.start<=t&&t<=s.end)??clip.scenes.findLast(s=>s.start<=t),svg=vertFrame(clip,sc,t);assert(!/NaN|undefined|Infinity/.test(svg));const f=out+'/frames/'+String(j).padStart(5,'0')+'.png';await sharp(Buffer.from(svg)).png().toFile(f);
 const cue=data.cues.findLast(q=>q.start<=t),header=Buffer.from(`<svg width="360" height="24"><rect width="360" height="24" fill="white"/><text x="8" y="18" font-family="sans-serif" font-size="16">${t.toFixed(3)}s ${cue.key}</text></svg>`);const tile=await sharp({create:{width:360,height:664,channels:3,background:'#fff'}}).composite([{input:header,left:0,top:0},{input:await sharp(f).resize(360,640).toBuffer(),left:0,top:24}]).jpeg({quality:92}).toBuffer();tiles.push(tile);rows.push({frame:j,time:t,cue:cue.key,raw:image.path,rawSha256:image.sha256,composite:f,compositeSha256:sha(f),actuallyViewed:false});
 if(tiles.length===10||i===p.actualImages.length-1){const page=Math.floor(i/10)+1,file=out+'/sheets/sheet-'+String(page).padStart(3,'0')+'.jpg';await sharp({create:{width:1800,height:1328,channels:3,background:'#fff'}}).composite(tiles.map((input,k)=>({input,left:k%5*360,top:Math.floor(k/5)*664}))).jpeg({quality:92}).toFile(file);pages.push({page,file,sha256:sha(file),actuallyViewed:false});tiles=[];}
}
const manifest={episode:'D-1',mode,sourceReport:reportFile,sourceReportSha256:sha(reportFile),helperSha256:p.helperSha256,actualFrames:rows.length,pages,frames:rows,previewOnlyNotEncodedMp4:true,allActuallyViewed:false,actualEarListeningDone:false,originalNGPreserved:true,finalAcceptance:false};fs.writeFileSync(out+'/manifest.json',JSON.stringify(manifest,null,1),{flag:'wx'});console.log(JSON.stringify({out,actualFrames:rows.length,pages:pages.length,allActuallyViewed:false}));
